  "unlock_description.webert_the_old": "\u0412\u044B\u0438\u0433\u0440\u0430\u0439\u0442\u0435 \u0438\u0433\u0440\u0443 \u0432 \u0431\u0435\u0441\u043A\u043E\u043D\u0435\u0447\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435, \u0447\u0442\u043E\u0431\u044B \u0440\u0430\u0437\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0412\u0435\u0431\u0435\u0440\u0442\u0430 \u0421\u0442\u0430\u0440\u043E\u0433\u043E.",
  "unlock_description.walking_reactor": "\u0414\u043E\u0441\u0442\u0438\u0433\u043D\u0438\u0442\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 20 \u0432 \u0431\u0435\u0441\u043A\u043E\u043D\u0435\u0447\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435, \u0447\u0442\u043E\u0431\u044B \u0440\u0430\u0437\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0425\u043E\u0434\u044F\u0447\u0438\u0439 \u0440\u0435\u0430\u043A\u0442\u043E\u0440.",
  "unlock_description.spectral_knight": "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0437\u043E\u043B\u043E\u0442\u0443\u044E \u043F\u043E\u0431\u0435\u0434\u0443 \u0441 \u041A\u0440\u0438\u0441\u0442\u0430\u043B\u043B\u043E\u043C \u043C\u0430\u043D\u044B, \u0447\u0442\u043E\u0431\u044B \u0440\u0430\u0437\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u041F\u0440\u0438\u0437\u0440\u0430\u0447\u043D\u043E\u0433\u043E \u0440\u044B\u0446\u0430\u0440\u044F.",
  "unlock_description.windlash_serpent": "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0437\u043E\u043B\u043E\u0442\u0443\u044E \u043F\u043E\u0431\u0435\u0434\u0443 \u0441 \u0411\u044B\u0441\u0442\u0440\u044B\u043C \u043A\u0430\u043C\u043D\u0435\u043C, \u0447\u0442\u043E\u0431\u044B \u0440\u0430\u0437\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0412\u0435\u0442\u0440\u043E\u0445\u043B\u0435\u0449\u0443\u0449\u0435\u0433\u043E \u0437\u043C\u0435\u044F.",
  "unlock_description.corruption_bringer": "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0437\u043E\u043B\u043E\u0442\u0443\u044E \u043F\u043E\u0431\u0435\u0434\u0443 \u0441 \u0424\u0438\u043E\u043B\u0435\u0442\u043E\u0432\u044B\u043C \u043A\u0440\u0438\u0441\u0442\u0430\u043B\u043B\u043E\u043C, \u0447\u0442\u043E\u0431\u044B \u0440\u0430\u0437\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u041D\u0435\u0441\u0443\u0449\u0435\u0433\u043E \u043F\u043E\u0440\u0447\u0443.",
  "unlock_description.frontline_dasher": "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0437\u043E\u043B\u043E\u0442\u0443\u044E \u043F\u043E\u0431\u0435\u0434\u0443 \u0441 \u041A\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u043C \u043A\u0440\u0438\u0441\u0442\u0430\u043B\u043B\u043E\u043C, \u0447\u0442\u043E\u0431\u044B \u0440\u0430\u0437\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u041F\u0435\u0440\u0435\u0434\u043E\u0432\u043E\u0439 \u0440\u044B\u0432\u043E\u043A.",
